local a={...}if type(a[1])~="string"or type(a[2])~="string"then print("Usage: attach <side> <type> [options...]")else if tonumber(a[3])~=nil then a[3]=tonumber(a[3])end;local b,c,d=coroutine.yield("syscall","attach",a[1],a[2],a[3])if not b then io.stderr:write("Could not attach peripheral"..(c and": "..c or"").."\n")elseif not c then io.stderr:write("Could not attach peripheral"..(d and": "..d or"").."\n")end end
